/*
 * PE/COFF header of barebox.efi
 *
 * barebox is linked as a position-independent ELF shared object and
 * relocates itself in _relocate() using the ELF dynamic relocations
 * embedded in the image. The PE/COFF header the firmware expects used to
 * be generated by objcopy's efi-app-* output targets, which exist only
 * in binutils and not in llvm-objcopy. Instead, this file provides the
 * header as assembler data placed at the start of the image, so that a
 * plain objcopy -O binary of the linked ELF yields a valid PE image.
 * The linker scripts lay out the ELF file such that virtual addresses
 * equal file offsets and the two PE sections start on section-aligned
 * boundaries.
 *
 * Modelled after arch/x86/boot/header.S and arch/arm64/kernel/efi-header.S
 * in Linux.
 *
 * All fields referencing the layout are written as differences to .L_head,
 * the start of the image, i.e. as PC-relative relocations against symbols
 * defined relative to a section. That includes the __pecoff_*_size
 * symbols, which the linker scripts define as image_base-relative
 * addresses for that reason. In a position-independent link, ld.bfd
 * rejects 32-bit absolute relocations (R_X86_64_32) and ld.lld silently
 * mis-resolves PC-relative relocations against absolute symbols, leaving
 * this the only form that works with both.
 */

#include <linux/pe.h>
#include <asm/barebox.lds.h>

	.section .efi.header, "a"
.L_head:
	/* MS-DOS stub: only the magic and the PE header pointer matter */
	.short	MZ_MAGIC
	.org	.L_head + 0x3c
	.long	.Lpe_header - .L_head

.Lpe_header:
	.long	PE_MAGIC
#ifdef CONFIG_X86_32
	.set	image_file_add_flags, IMAGE_FILE_32BIT_MACHINE
	.set	pe_opt_magic, PE_OPT_MAGIC_PE32
	.short	IMAGE_FILE_MACHINE_I386			/* Machine */
#else
	.set	image_file_add_flags, 0
	.set	pe_opt_magic, PE_OPT_MAGIC_PE32PLUS
	.short	IMAGE_FILE_MACHINE_AMD64		/* Machine */
#endif
	.short	.Lsection_count				/* NumberOfSections */
	.long	0					/* TimeDateStamp */
	.long	0					/* PointerToSymbolTable */
	.long	0					/* NumberOfSymbols */
	.short	.Lsection_table - .Loptional_header	/* SizeOfOptionalHeader */
	.short	IMAGE_FILE_EXECUTABLE_IMAGE | \
		IMAGE_FILE_LINE_NUMS_STRIPPED | \
		IMAGE_FILE_DEBUG_STRIPPED | \
		image_file_add_flags			/* Characteristics */

.Loptional_header:
	.short	pe_opt_magic				/* Magic */
	.byte	0x02					/* MajorLinkerVersion */
	.byte	0x14					/* MinorLinkerVersion */
	.long	__pecoff_text_size - .L_head		/* SizeOfCode */
	.long	__pecoff_data_size - .L_head		/* SizeOfInitializedData */
	.long	0					/* SizeOfUninitializedData */
	.long	_start - .L_head			/* AddressOfEntryPoint */
	.long	_stext - .L_head			/* BaseOfCode */
#ifdef CONFIG_X86_32
	.long	_sdata - .L_head			/* BaseOfData */
	.long	0					/* ImageBase */
#else
	.quad	0					/* ImageBase */
#endif
	.long	PECOFF_SECTION_ALIGNMENT		/* SectionAlignment */
	.long	PECOFF_FILE_ALIGNMENT			/* FileAlignment */
	.short	0					/* MajorOperatingSystemVersion */
	.short	0					/* MinorOperatingSystemVersion */
	.short	0					/* MajorImageVersion */
	.short	0					/* MinorImageVersion */
	.short	0					/* MajorSubsystemVersion */
	.short	0					/* MinorSubsystemVersion */
	.long	0					/* Win32VersionValue */
	.long	__image_end - .L_head			/* SizeOfImage */
	.long	.Lefi_header_end - .L_head		/* SizeOfHeaders */
	.long	0					/* CheckSum */
	.short	IMAGE_SUBSYSTEM_EFI_APPLICATION		/* Subsystem */
	.short	0					/* DllCharacteristics */
#ifdef CONFIG_X86_32
	.long	0					/* SizeOfStackReserve */
	.long	0					/* SizeOfStackCommit */
	.long	0					/* SizeOfHeapReserve */
	.long	0					/* SizeOfHeapCommit */
#else
	.quad	0					/* SizeOfStackReserve */
	.quad	0					/* SizeOfStackCommit */
	.quad	0					/* SizeOfHeapReserve */
	.quad	0					/* SizeOfHeapCommit */
#endif
	.long	0					/* LoaderFlags */
	.long	(.Lsection_table - .) / 8		/* NumberOfRvaAndSizes */

	.quad	0					/* ExportTable */
	.quad	0					/* ImportTable */
	.quad	0					/* ResourceTable */
	.quad	0					/* ExceptionTable */
	.quad	0					/* CertificateTable */
	/*
	 * No PE relocations: relocation happens in _relocate() using the
	 * ELF dynamic relocations. An empty base relocation table is what
	 * Linux ships as well, since the dummy .reloc section for ancient
	 * buggy loaders was dropped in v6.7.
	 */
	.quad	0					/* BaseRelocationTable */

.Lsection_table:
	.ascii	".text\0\0\0"
	.long	__pecoff_text_size - .L_head		/* VirtualSize */
	.long	_stext - .L_head			/* VirtualAddress */
	.long	__pecoff_text_size - .L_head		/* SizeOfRawData */
	.long	_stext - .L_head			/* PointerToRawData */
	.long	0					/* PointerToRelocations */
	.long	0					/* PointerToLineNumbers */
	.short	0					/* NumberOfRelocations */
	.short	0					/* NumberOfLineNumbers */
	.long	IMAGE_SCN_CNT_CODE | \
		IMAGE_SCN_MEM_READ | \
		IMAGE_SCN_MEM_EXECUTE			/* Characteristics */

	/*
	 * Everything else, including .rodata, .bss and the ELF dynamic
	 * relocation tables, is one writable data section: applying the
	 * relocations at startup writes to all of it.
	 */
	.ascii	".data\0\0\0"
	.long	__pecoff_data_size - .L_head		/* VirtualSize */
	.long	_sdata - .L_head			/* VirtualAddress */
	.long	__pecoff_data_rawsize - .L_head		/* SizeOfRawData */
	.long	_sdata - .L_head			/* PointerToRawData */
	.long	0					/* PointerToRelocations */
	.long	0					/* PointerToLineNumbers */
	.short	0					/* NumberOfRelocations */
	.short	0					/* NumberOfLineNumbers */
	.long	IMAGE_SCN_CNT_INITIALIZED_DATA | \
		IMAGE_SCN_MEM_READ | \
		IMAGE_SCN_MEM_WRITE			/* Characteristics */

	.set	.Lsection_count, (. - .Lsection_table) / 40

	/* Pad the header so .text starts on a section-aligned boundary */
	.balign	PECOFF_SECTION_ALIGNMENT
.Lefi_header_end:
